<?php
namespace ExcelHerbal\ERP7\Security;
use ExcelHerbal\ERP7\Database\Db;
use ExcelHerbal\ERP7\Database\Transaction;
use ExcelHerbal\ERP7\Domain\DomainException;

final class AccessService {
    /** @return string[] */ private static function knownCapabilities():array{return array_values(array_unique(array_values((new \ReflectionClass(Capabilities::class))->getConstants())));}
    public static function matrix(Actor $a):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);$db=Db::wpdb();$roles=(array)$db->get_results($db->prepare("SELECT id,code,name,active FROM ".Db::table('roles')." WHERE company_id=%d ORDER BY name",$a->companyId),ARRAY_A);foreach($roles as&$r){$r['capabilities']=(array)$db->get_col($db->prepare("SELECT capability FROM ".Db::table('role_capabilities')." WHERE role_id=%d AND active=1 ORDER BY capability",(int)$r['id']));}unset($r);return['capabilities'=>self::knownCapabilities(),'roles'=>$roles];}
    public static function createRole(Actor $a,string $code,string $name):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);$code=strtoupper(trim($code));$name=trim($name);if($code===''||$name==='')throw new DomainException('Role code and name are required.','role_fields_required',422);$db=Db::wpdb();Db::mustInsert($db,Db::table('roles'),['company_id'=>$a->companyId,'code'=>$code,'name'=>$name,'active'=>1]);if(!$db->insert_id)throw new DomainException('Role code already exists.','role_duplicate',409);$id=(int)$db->insert_id;Audit::add($a,'access.role_create','role',$id,['code'=>$code]);return['id'=>$id,'code'=>$code,'name'=>$name,'active'=>true];}
    public static function setRoleCapabilities(Actor $a,int $roleId,array $caps,string $reason):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);if(strlen(trim($reason))<5)throw new DomainException('Access-change reason is required.','access_reason_required',422);$known=self::knownCapabilities();$wanted=array_values(array_unique(array_map('strval',$caps)));if(array_diff($wanted,$known))throw new DomainException('Unknown capability supplied.','capability_invalid',422);return Transaction::run(function()use($a,$roleId,$wanted,$reason,$known){$db=Db::wpdb();$role=$db->get_row($db->prepare("SELECT * FROM ".Db::table('roles')." WHERE id=%d AND company_id=%d AND active=1 FOR UPDATE",$roleId,$a->companyId),ARRAY_A);if(!$role)throw new DomainException('Active role not found.','role_not_found',404);$selfAssigned=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('employee_roles')." WHERE company_id=%d AND employee_id=%d AND role_id=%d AND active=1",$a->companyId,$a->employeeId,$roleId));if($selfAssigned&&(!in_array(Capabilities::ACCESS,$wanted,true)||!in_array(Capabilities::ACCESS_MANAGE,$wanted,true)))throw new DomainException('Cannot remove own ERP/access-management capability through an assigned role.','self_access_lockout',409);$t=Db::table('role_capabilities');$before=(array)$db->get_col($db->prepare("SELECT capability FROM {$t} WHERE role_id=%d AND active=1 ORDER BY capability",$roleId));$rows=(array)$db->get_results($db->prepare("SELECT id,capability,active FROM {$t} WHERE role_id=%d",$roleId),ARRAY_A);$by=[];foreach($rows as$r)$by[(string)$r['capability']]=$r;foreach($known as$cap){$active=in_array($cap,$wanted,true)?1:0;if(isset($by[$cap]))$db->update($t,['active'=>$active,'updated_at'=>Db::now()],['id'=>(int)$by[$cap]['id']]);elseif($active)Db::mustInsert($db,$t,['role_id'=>$roleId,'capability'=>$cap,'active'=>1,'created_at'=>Db::now()]);}Audit::add($a,'access.role_capabilities','role',$roleId,['before'=>$before,'after'=>$wanted,'reason'=>trim($reason)]);return['role_id'=>$roleId,'capabilities'=>$wanted];});}
    public static function employeeAccess(Actor $a,int $employeeId):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT id,full_name,assigned_branch_id,status FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);if(!$a->hasBranch((int)$e['assigned_branch_id']))throw new DomainException('Employee branch is outside effective authority.','branch_forbidden',403);$roles=(array)$db->get_results($db->prepare("SELECT r.id,r.code,r.name FROM ".Db::table('employee_roles')." er JOIN ".Db::table('roles')." r ON r.id=er.role_id AND r.active=1 WHERE er.company_id=%d AND er.employee_id=%d AND er.active=1 ORDER BY r.name",$a->companyId,$employeeId),ARRAY_A);return['employee'=>$e,'roles'=>$roles,'branch_ids'=>BranchAuthority::ids($employeeId,$a->companyId)];}
    public static function setEmployeeRoles(Actor $a,int $employeeId,array $roleIds,string $reason):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);if(strlen(trim($reason))<5)throw new DomainException('Access-change reason is required.','access_reason_required',422);$wanted=array_values(array_unique(array_filter(array_map('intval',$roleIds))));if(!$wanted)throw new DomainException('At least one active role is required.','employee_role_required',422);return Transaction::run(function()use($a,$employeeId,$wanted,$reason){$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT id,assigned_branch_id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d AND status='active' FOR UPDATE",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Active employee not found.','employee_not_found',404);if(!$a->hasBranch((int)$e['assigned_branch_id']))throw new DomainException('Employee branch is outside effective authority.','branch_forbidden',403);$place=implode(',',array_fill(0,count($wanted),'%d'));$args=array_merge([$a->companyId],$wanted);$valid=array_map('intval',(array)$db->get_col($db->prepare("SELECT id FROM ".Db::table('roles')." WHERE company_id=%d AND active=1 AND id IN ({$place})",...$args)));sort($valid);$sorted=$wanted;sort($sorted);if($valid!==$sorted)throw new DomainException('One or more roles are invalid.','role_invalid',422);if($employeeId===$a->employeeId){$caps=(array)$db->get_col($db->prepare("SELECT DISTINCT capability FROM ".Db::table('role_capabilities')." WHERE active=1 AND role_id IN ({$place})",...$wanted));if(!in_array(Capabilities::ACCESS,$caps,true)||!in_array(Capabilities::ACCESS_MANAGE,$caps,true))throw new DomainException('Cannot remove own ERP/access-management capability.','self_access_lockout',409);} $t=Db::table('employee_roles');$before=array_map('intval',(array)$db->get_col($db->prepare("SELECT role_id FROM {$t} WHERE company_id=%d AND employee_id=%d AND active=1 ORDER BY role_id",$a->companyId,$employeeId)));$rows=(array)$db->get_results($db->prepare("SELECT id,role_id FROM {$t} WHERE company_id=%d AND employee_id=%d",$a->companyId,$employeeId),ARRAY_A);$by=[];foreach($rows as$r)$by[(int)$r['role_id']]=$r;foreach($by as$rid=>$r)if(!in_array($rid,$wanted,true))$db->update($t,['active'=>0,'revoked_at'=>Db::now()],['id'=>(int)$r['id']]);foreach($wanted as$rid){if(isset($by[$rid]))$db->update($t,['active'=>1,'assigned_by'=>$a->employeeId,'assigned_at'=>Db::now(),'revoked_at'=>null],['id'=>(int)$by[$rid]['id']]);elseDb::mustInsert($db,$t,['company_id'=>$a->companyId,'employee_id'=>$employeeId,'role_id'=>$rid,'active'=>1,'assigned_by'=>$a->employeeId,'assigned_at'=>Db::now()]);}Audit::add($a,'access.employee_roles','employee',$employeeId,['before'=>$before,'after'=>$wanted,'reason'=>trim($reason),'branch_id'=>(int)$e['assigned_branch_id']]);return['employee_id'=>$employeeId,'role_ids'=>$wanted];});}
}
